test("SDK failure uses thread.id when thread.started is absent",async()=>{class FakeCodex{constructor(_options:unknown){}startThread(_options:unknown){return{id:"object-thread",runStreamed:async()=>({events:(async function*(){yield goodEvents[1];throw new Error("terminal")})()})};}}await assert.rejects(()=>new SdkCodexExecutor(FakeCodex as any).execute({} as any,{} as any,"prompt"),error=>{assert.equal((error as CodexExecutionError).threadId,"object-thread");assert.equal((error as CodexExecutionError).events.length,1);return true;});});
