test("rollout recovery rejects ambiguous, duplicate, escaped, and unreadable evidence",async()=>{await assert.rejects(()=>recovery(successRollout("current-thread",{extraSession:true})),/COMPATIBILITY_PROBE_FAILED/);const exact=successRollout("current-thread");const {isolation}=rolloutFilesIsolation({"rollout-a.jsonl":exact,"rollout-b.jsonl":exact});await assert.rejects(()=>runCompatibilityProbe(falseNegativeExecutor(),"v/m:free","w",{},"clean",()=>"clean",now,isolation),/COMPATIBILITY_PROBE_FAILED/);await assert.rejects(()=>recovery(undefined),/COMPATIBILITY_PROBE_FAILED/);await assert.rejects(()=>recovery("{"),/COMPATIBILITY_PROBE_FAILED/);const unreadable=rolloutFilesIsolation({"rollout.jsonl":new Error("read denied")});await assert.rejects(()=>runCompatibilityProbe(falseNegativeExecutor(),"v/m:free","w",{},"clean",()=>"clean",now,unreadable.isolation),/COMPATIBILITY_PROBE_FAILED/);const home="C:\\synthetic-local\\print-engineer-codex\\openrouter-home-v1";const sessions=home+"\\sessions";const linked=rolloutFilesIsolation({"rollout.jsonl":exact},new Set([sessions+"\\rollout.jsonl"]));await assert.rejects(()=>runCompatibilityProbe(falseNegativeExecutor(),"v/m:free","w",{},"clean",()=>"clean",now,linked.isolation),/COMPATIBILITY_PROBE_FAILED/);const escapeCase=rolloutFilesIsolation({});const fs:any=escapeCase.isolation.filesystem;fs.readdir=(path:string)=>path===sessions?["..\\..\\evil"]:path===home?["sessions"]:undefined;await assert.rejects(()=>runCompatibilityProbe(falseNegativeExecutor(),"v/m:free","w",{},"clean",()=>"clean",now,escapeCase.isolation),/COMPATIBILITY_PROBE_FAILED/);});
test("rollout recovery requires AGENTS.md shell_command, exact call_id, and canonical exit 0",async()=>{for(const content of [successRollout("current-thread",{calls:[{callId:"call-1",command:"Get-Content README.md",output:ENVELOPE_0}]}),successRollout("current-thread",{calls:[{callId:"call-1",command:"Get-Content AGENTS.md",output:ENVELOPE_0,outputCallId:"call-other"}]}),successRollout("current-thread",{calls:[{callId:"call-1",command:"Get-Content AGENTS.md",output:ENVELOPE_1}]}),successRollout("current-thread",{calls:[{callId:"call-1",command:"Get-Content AGENTS.md",output:"Output:\n# Codex Project Execution Contract"}]}),successRollout("current-thread",{calls:[{callId:"call-1",command:"Get-Content AGENTS.md",output:"Exit code: 0 Wall time: 0.2 seconds\nOutput:\nbody"}]}),successRollout("current-thread",{calls:[{callId:"call-1",command:"Get-Content AGENTS.md",output:"Process exited with code 0\nmore output\n"}]})])await assert.rejects(()=>recovery(content),/COMPATIBILITY_PROBE_FAILED/);});
test("rollout recovery requires non-empty post-tool assistant response",async()=>{for(const content of [successRollout("current-thread",{preTool:"only before",postTool:[]}),successRollout("current-thread",{postTool:[{agent:"",message:"   "}]})])await assert.rejects(()=>recovery(content),/COMPATIBILITY_PROBE_FAILED/);});
