test("item_error rollout recovery CLI success output stays clean",async()=>{const env={CODEX_PROVIDER_MODE:"openrouter-free",OPENROUTER_API_KEY:"synthetic",CODEX_COMPATIBILITY_MODEL:"v/m:free",MODEL_WORKDIR:"w"};const fetcher=async(input:string)=>new Response(JSON.stringify(input.includes("/model/")?{data:model()}:{data:[model()],total_count:1}),{status:200});const lines:string[]=[];const exit=await runControllerCli(["--compatibility-probe"],env,{fetcher:fetcher as typeof fetch,executor:{execute:async()=>({threadId:"current-thread",events:itemErrorEvents(),finalResponse:""})} as any,gitStatus:()=>"clean",validateWorktree:()=>"w",isolation:rolloutIsolation(successRollout("current-thread"))},line=>lines.push(line),()=>{});assert.equal(exit,0);assert.deepEqual(lines,["model_id=v/m:free","codex_sdk_version=0.147.0","provider_id=openrouter","wire_api=responses","tool_loop_success=true","final_completion_success=true","worktree_unchanged=true"]);});
test("rollout recovery cannot bypass qualification and preflight gates",async()=>{let executions=0;const env={CODEX_PROVIDER_MODE:"openrouter-free",OPENROUTER_API_KEY:"synthetic",CODEX_COMPATIBILITY_MODEL:"v/m:free",MODEL_WORKDIR:"w"};const executor:any={execute:async()=>{executions++;return{threadId:"current-thread",events:[{type:"thread.started",thread_id:"current-thread"}],finalResponse:""}}};const fetcher=async(input:string)=>new Response(JSON.stringify(input.includes("/model/")?{data:model()}:{data:[model()],total_count:1}),{status:200});const report=await executeCompatibilityProbe(env,"w",{fetcher,executor,gitStatus:()=>"clean",now:()=>now,isolation:rolloutIsolation(successRollout("current-thread"))});assert.equal(report.worktree_unchanged,true);assert.equal(executions,1);for(const bad of [model({pricing:{prompt:"1",completion:"0",request:"0"}}),model({id:"v/m"})])await assert.rejects(()=>executeCompatibilityProbe(env,"w",{fetcher:async(input:string)=>new Response(JSON.stringify(input.includes("/model/")?{data:bad}:{data:[model()],total_count:1}),{status:200}),executor,gitStatus:()=>"clean",now:()=>now,isolation:rolloutIsolation(successRollout("current-thread"))}),/COMPATIBILITY_PROBE_FAILED/);assert.equal(executions,1);});
async function diagnosticsOf(run:()=>Promise<unknown>):Promise<ProbeDiagnostics>{let rejected=false;let error:unknown;try{await run();}catch(e){rejected=true;error=e;}assert.equal(rejected,true);assert.ok(error instanceof CompatibilityProbeDiagnosticsError);return error.diagnostics;}
test("diagnostics classify failure before executor and registry isolation",async()=>{const urls:string[]=[];const d=await diagnosticsOf(()=>executeCompatibilityProbe({CODEX_PROVIDER_MODE:"openrouter-free",OPENROUTER_API_KEY:"synthetic",CODEX_COMPATIBILITY_MODEL:"v/m:free"},"w",{fetcher:async(input:string)=>{urls.push(input);throw new Error("catalog secret body")},executor:{execute:async()=>{throw new Error("MUST_NOT_RUN")}} as any,gitStatus:()=>"x",now:()=>now}));assert.equal(d.failure_before_executor,true);assert.equal(d.executor_threw_codex_error,false);assert.equal(d.executor_threw_non_codex_error,false);assert.equal(d.executor_returned_normal_execution_result,false);assert.equal(d.evaluate_probe_failed,false);assert.equal(d.rollout_recovery_attempted,false);assert.equal(d.rollout_correlation_failure_category,"none");assert.equal(d.worktree_equal,false);assert.equal(urls.length,1);await assert.rejects(()=>dispatchControllerCommand(["--compatibility-probe"],{CODEX_PROVIDER_MODE:"openrouter-free",OPENROUTER_API_KEY:"synthetic",CODEX_COMPATIBILITY_MODEL:"v/m:free"},{fetcher:async()=>{throw 0},executor:{execute:async()=>{throw new Error("MUST_NOT_RUN")}} as any}),error=>{assert.ok(error instanceof CompatibilityProbeDiagnosticsError);assert.equal(error.diagnostics.failure_before_executor,true);return true;});});
test("diagnostics classify thrown CodexExecutionError with status thread id and captured events",async()=>{const rateLimited={type:"turn.failed",error:{codex_error_info:{response_too_many_failed_attempts:{http_status_code:429}},message:"429 Too Many Requests"}};const events=[{type:"thread.started",thread_id:"t"},rateLimited];const d=await diagnosticsOf(()=>runCompatibilityProbe({execute:async()=>{throw new CodexExecutionError(400,events as any,"t")}} as any,"v/m:free","w",{},"clean",()=>"clean",now,isolation));assert.equal(d.executor_threw_codex_error,true);assert.equal(d.executor_threw_non_codex_error,false);assert.equal(d.executor_returned_normal_execution_result,false);assert.equal(d.executor_http_status_present,true);assert.equal(d.executor_thread_id_present,true);assert.equal(d.executor_captured_event_count,2);assert.equal(d.captured_structured_http_429,true);assert.equal(d.captured_turn_failed,true);assert.equal(d.captured_error,false);assert.equal(d.captured_item_error,false);assert.equal(d.rollout_recovery_attempted,false);assert.equal(d.rollout_correlation_failure_category,"unreadable");assert.equal(d.worktree_equal,true);});
test("diagnostics classify bare thrown CodexExecutionError",async()=>{const d=await diagnosticsOf(()=>runCompatibilityProbe({execute:async()=>{throw new CodexExecutionError()}} as any,"v/m:free","w",{},"clean",()=>"clean",now,isolation));assert.equal(d.executor_threw_codex_error,true);assert.equal(d.executor_http_status_present,false);assert.equal(d.executor_thread_id_present,false);assert.equal(d.executor_captured_event_count,0);assert.equal(d.captured_structured_http_429,false);assert.equal(d.rollout_recovery_attempted,false);assert.equal(d.worktree_equal,true);});
test("diagnostics classify thrown non-Codex executor error and never success",async()=>{let calls=0;const d=await diagnosticsOf(()=>runCompatibilityProbe({execute:async()=>{calls++;throw new Error("provider body secret")}} as any,"v/m:free","w",{},"clean",()=>"clean",now,isolation));assert.equal(calls,1);assert.equal(d.executor_threw_non_codex_error,true);assert.equal(d.executor_threw_codex_error,false);assert.equal(d.executor_http_status_present,false);assert.equal(d.executor_thread_id_present,false);assert.equal(d.executor_captured_event_count,0);assert.equal(d.worktree_equal,true);assert.equal(diagnosticLines(d).join("\n").includes("provider body secret"),false);});
test("diagnostics record captured terminal flags and worktree inequality",async()=>{const events=[{type:"thread.started",thread_id:"t"},{type:"turn.failed",error:{message:"x"}},{type:"error",message:"stream"},{type:"item.completed",item:{type:"error",id:"e",message:"item"}}];const d=await diagnosticsOf(()=>runCompatibilityProbe({execute:async()=>{throw new CodexExecutionError(400,events as any,"t")}} as any,"v/m:free","w",{},"clean",()=>"changed",now,isolation));assert.equal(d.worktree_equal,false);assert.equal(d.captured_turn_failed,true);assert.equal(d.captured_error,true);assert.equal(d.captured_item_error,true);assert.equal(d.executor_threw_codex_error,true);});
test("diagnostics classify normal ExecutionResult failure and presence facts",async()=>{const d=await diagnosticsOf(()=>runCompatibilityProbe({execute:async()=>({finalResponse:"",events:[]})} as any,"v/m:free","w",{},"clean",()=>"clean",now,isolation));assert.equal(d.executor_returned_normal_execution_result,true);assert.equal(d.executor_threw_codex_error,false);assert.equal(d.executor_threw_non_codex_error,false);assert.equal(d.normal_result_thread_id_present,false);assert.equal(d.normal_result_terminal_sdk_event_present,false);assert.equal(d.evaluate_probe_success,false);assert.equal(d.evaluate_probe_failed,true);assert.equal(d.rollout_recovery_attempted,false);assert.equal(d.rollout_correlation_failure_category,"none");assert.equal(d.worktree_equal,true);const terminal=await diagnosticsOf(()=>runCompatibilityProbe({execute:async()=>({threadId:"t",events:[{type:"thread.started",thread_id:"t"},{type:"turn.failed",error:{message:"x"}}],finalResponse:""})} as any,"v/m:free","w",{},"clean",()=>"clean",now,isolation));assert.equal(terminal.normal_result_thread_id_present,true);assert.equal(terminal.normal_result_terminal_sdk_event_present,true);assert.equal(terminal.rollout_recovery_attempted,false);});
test("diagnostics record SDK evaluator success and recovery outcomes",async()=>{const report=await runCompatibilityProbe({execute:async()=>({finalResponse:"# heading",events:goodEvents})} as any,"v/m:free","w",{},"clean",()=>"clean",now,isolation);assert.equal(report.diagnostics.evaluate_probe_success,true);assert.equal(report.diagnostics.evaluate_probe_failed,false);assert.equal(report.diagnostics.executor_returned_normal_execution_result,true);assert.equal(report.diagnostics.rollout_recovery_attempted,false);const recovered=await runCompatibilityProbe(falseNegativeExecutor(),"v/m:free","w",{},"clean",()=>"clean",now,rolloutIsolation(successRollout("current-thread")));assert.equal(recovered.diagnostics.rollout_recovery_attempted,true);assert.equal(recovered.diagnostics.rollout_success_evidence,true);assert.equal(recovered.diagnostics.rollout_correlation_failure_category,"none");assert.equal(recovered.diagnostics.evaluate_probe_failed,true);});
test("diagnostics record recovery attempt and correlation categories",async()=>{const corrupt=await diagnosticsOf(()=>recovery("{"));assert.equal(corrupt.rollout_recovery_attempted,true);assert.equal(corrupt.rollout_success_evidence,false);assert.equal(corrupt.rollout_correlation_failure_category,"corrupt");assert.equal(corrupt.evaluate_probe_failed,true);for(const [content,expected] of [[successRollout("current-thread",{provider:"wrong-provider"}),"wrong_provider"],[successRollout("current-thread",{cwd:"other-worktree"}),"wrong_cwd"],[successRollout("current-thread",{turnModel:"other:free"}),"wrong_model"],[successRollout("current-thread",{sessionModel:false,turnModel:false}),"wrong_model"]] as const){const d=await diagnosticsOf(()=>recovery(content));assert.equal(d.rollout_correlation_failure_category,expected);}});
test("diagnostics record session duplicate escape containment unreadable and missing categories",async()=>{const home="C:\\synthetic-local\\print-engineer-codex\\openrouter-home-v1";const sessions=home+"\\sessions";const conflicting=rolloutContent("current-thread")+"\n"+JSON.stringify({type:"session_meta",payload:{id:"other-thread",model_provider:"openrouter",cwd:"w",model:"v/m:free"}});let d=await diagnosticsOf(()=>runCompatibilityProbe(throwingSdk(),"v/m:free","w",{},"clean",()=>"clean",now,rolloutIsolation(conflicting)));assert.equal(d.rollout_correlation_failure_category,"session_metadata");const duplicate=rolloutFilesIsolation({"rollout-a.jsonl":rolloutContent("current-thread"),"rollout-b.jsonl":rolloutContent("current-thread")});d=await diagnosticsOf(()=>runCompatibilityProbe(throwingSdk(),"v/m:free","w",{},"clean",()=>"clean",now,duplicate.isolation));assert.equal(d.rollout_correlation_failure_category,"multiple_exact_sessions");const linked=rolloutFilesIsolation({"rollout.jsonl":rolloutContent("current-thread")},new Set([sessions+"\\rollout.jsonl"]));d=await diagnosticsOf(()=>runCompatibilityProbe(throwingSdk(),"v/m:free","w",{},"clean",()=>"clean",now,linked.isolation));assert.equal(d.rollout_correlation_failure_category,"symlink_escape");const unreadable=rolloutFilesIsolation({"rollout-unreadable.jsonl":new Error("read denied")});d=await diagnosticsOf(()=>runCompatibilityProbe(throwingSdk(),"v/m:free","w",{},"clean",()=>"clean",now,unreadable.isolation));assert.equal(d.rollout_correlation_failure_category,"unreadable");d=await diagnosticsOf(()=>runCompatibilityProbe(throwingSdk(),"v/m:free","w",{},"clean",()=>"clean",now,rolloutIsolation(undefined)));assert.equal(d.rollout_correlation_failure_category,"uncorrelated");const escapeCase=rolloutFilesIsolation({});const fs:any=escapeCase.isolation.filesystem;fs.readdir=(path:string)=>path===sessions?["..\\..\\evil"]:path===home?["sessions"]:undefined;d=await diagnosticsOf(()=>runCompatibilityProbe(throwingSdk(),"v/m:free","w",{},"clean",()=>"clean",now,escapeCase.isolation));assert.equal(d.rollout_correlation_failure_category,"path_containment");});
test("diagnostic lines are fixed safe values only",async()=>{const lines=diagnosticLines(emptyProbeDiagnostics());assert.equal(lines.length,19);for(const line of lines)assert.match(line,/^[a-z0-9_]+=(true|false|[0-9]+|none|wrong_provider|wrong_cwd|wrong_model|session_metadata|multiple_exact_sessions|symlink_escape|path_containment|unreadable|corrupt|uncorrelated)$/);});
test("thrown successful-looking rollout remains FAILED with diagnostics and one invocation",async()=>{let calls=0;await assert.rejects(()=>runCompatibilityProbe({execute:async()=>{calls++;throw new Error("terminal")}} as any,"v/m:free","w",{},"clean",()=>"clean",now,rolloutIsolation(successRollout("current-thread"))),error=>{assert.ok(error instanceof CompatibilityProbeDiagnosticsError);assert.equal(error.diagnostics.executor_threw_non_codex_error,true);assert.equal(error.diagnostics.rollout_recovery_attempted,false);assert.equal(error.diagnostics.rollout_success_evidence,false);assert.equal(error.diagnostics.rollout_correlation_failure_category,"none");return true;});assert.equal(calls,1);});
test("RATE_LIMITED and SUCCESS CLI outputs gain no diagnostic lines",async()=>{const env={CODEX_PROVIDER_MODE:"openrouter-free",OPENROUTER_API_KEY:"synthetic",CODEX_COMPATIBILITY_MODEL:"v/m:free",MODEL_WORKDIR:"w"};const fetcher=async(input:string)=>new Response(JSON.stringify(input.includes("/model/")?{data:model()}:{data:[model()],total_count:1}),{status:200});const rateErrors:string[]=[];const rate=await runControllerCli(["--compatibility-probe"],env,{fetcher:fetcher as typeof fetch,executor:{execute:async()=>{throw new CodexExecutionError(429)}} as any,gitStatus:()=>"clean",validateWorktree:w=>w,isolation},()=>{},line=>rateErrors.push(line));assert.equal(rate,1);assert.deepEqual(rateErrors,[COMPATIBILITY_PROBE_RATE_LIMITED]);const successLines:string[]=[];const success=await runControllerCli(["--compatibility-probe"],env,{fetcher:fetcher as typeof fetch,executor:{execute:async()=>({finalResponse:"# heading",events:goodEvents})} as any,gitStatus:()=>"clean",validateWorktree:w=>w,isolation},line=>successLines.push(line),()=>{});assert.equal(success,0);assert.equal(successLines.join("\n").includes("executor_returned_normal_execution_result"),false);});
test("FAILED CLI diagnostic output leaks no prompt model text rollout or raw error content",async()=>{const env={CODEX_PROVIDER_MODE:"openrouter-free",OPENROUTER_API_KEY:"synthetic",CODEX_COMPATIBILITY_MODEL:"v/m:free",MODEL_WORKDIR:"w"};const fetcher=async(input:string)=>new Response(JSON.stringify(input.includes("/model/")?{data:model()}:{data:[model()],total_count:1}),{status:200});const errors:string[]=[];await runControllerCli(["--compatibility-probe"],env,{fetcher:fetcher as typeof fetch,executor:{execute:async()=>{throw new CodexExecutionError(400,[{type:"turn.failed",error:{message:"raw provider body"}}],"t")}} as any,gitStatus:()=>"clean",validateWorktree:w=>w,isolation},()=>{},line=>errors.push(line));const joined=errors.join("\n");assert.ok(joined.startsWith(COMPATIBILITY_PROBE_FAILED+"\n"));for(const forbidden of ["raw provider body",COMPATIBILITY_PROMPT,"# heading","OPENROUTER_API_KEY","synthetic","Exit code"])assert.equal(joined.includes(forbidden),false);});
